      val.catch = (fn) => safe(val);
    }
    return val;
  }
  return { ...val, then: (resolve) => resolve(val), catch: (fn) => safe(val) };
}

// Simple query builder
function query(table) {
  const filters = [];
  let limitVal = null, singleMode = false, orderCol = null, orderAsc = true;
  const b = {
    select: () => b,
    eq: (col, val) => { filters.push({ type: 'eq', col, val }); return b; },
    gte: (col, val) => { filters.push({ type: 'gte', col, val }); return b; },
    lte: (col, val) => { filters.push({ type: 'lte', col, val }); return b; },
    not: (col, val) => { filters.push({ type: 'not', col, val }); return b; },
    is: (col, val) => { filters.push({ type: 'is', col, val }); return b; },
    in: (col, vals) => { filters.push({ type: 'in', col, vals }); return b; },
    order: (col, opts) => { orderCol = col; orderAsc = opts?.ascending !== false; return b; },
    limit: (n) => { limitVal = n; return b; },
    single: () => { singleMode = true; return b; },
    maybeSingle: () => { singleMode = true; return b; },
    then: (resolve) => {
      let rows = getTable(table);
      rows = rows.filter(r => filters.every(f => {
        try {
          if (f.type === 'eq') return r[f.col] === f.val;
          if (f.type === 'gte') return new Date(r[f.col]) >= new Date(f.val);
          if (f.type === 'lte') return new Date(r[f.col]) <= new Date(f.val);
          if (f.type === 'not') return r[f.col] !== f.val;
          if (f.type === 'is') return r[f.col] === null || r[f.col] === undefined;
          if (f.type === 'in') return f.vals.includes(r[f.col]);
          return true;
        } catch { return false; }
      }));
      if (orderCol) rows.sort((a, b) => (a[orderCol] > b[orderCol] ? 1 : -1) * (orderAsc ? 1 : -1));
