function dbInsert(table, payload) {
  const rows = getTable(table);
  const arr = Array.isArray(payload) ? payload : [payload];
  const newRows = arr.map(d => {
    const base = { id: id(), ...d };
    if (table === 'sales' && !base.invoice_number) base.invoice_number = '' + (rows.length + 1);
    return base;
  });
  setTable(table, [...rows, ...newRows]);
  const res = safe({ data: newRows, error: null });
  res.select = () => safe({ data: newRows, error: null });
  res.single = () => safe({ data: newRows[0] || null, error: null });
  return res;
}

function dbUpdate(table, data, filters) {
  const rows = getTable(table);
  const updated = rows.map(r => filters.every(f => r[f.col] === f.val) ? { ...r, ...data } : r);
  setTable(table, updated);
  return safe({ error: null });
}

function dbDelete(table, filters) {
  const rows = getTable(table);
  const remaining = rows.filter(r => !filters.every(f => r[f.col] === f.val));
  setTable(table, remaining);
  return safe({ error: null });
}

function dbUpsert(table, payload) {
  const rows = getTable(table);
  const arr = Array.isArray(payload) ? payload : [payload];
  arr.forEach(d => {
    const idx = rows.findIndex(r => r.id === d.id);
    if (idx >= 0) rows[idx] = d;
    else rows.push({ id: id(), ...d });
  });
  setTable(table, rows);
  return safe({ error: null });
}

