  from: (table) => ({
    select: (cols, opts) => {
      const q = query(table);
      if (opts?.count === 'exact') {
        q._count = true;
        q._head = opts.head || false;
      }
      return q;
    },
    insert: (data) => dbInsert(table, data),
    update: (data) => ({
      eq: (col, val) => dbUpdate(table, data, [{ type: 'eq', col, val }]),
      in: (col, vals) => dbUpdate(table, data, [{ type: 'in', col, vals }]),
    }),
